# owner: platform
import unittest

from rosterkit.contacts import contact_rows
from rosterkit.models import Student


class ContactRowTests(unittest.TestCase):
    def test_rows_are_sorted_and_aligned(self):
        rows = contact_rows(
            [
                Student("2", "Young", "Zed", "B12", "zed@example.org"),
                Student("1", "Abel", "Amy", "A1", "amy@example.org"),
            ]
        )
        self.assertEqual(
            rows,
            ["Abel, Amy   A1   amy@example.org", "Young, Zed  B12  zed@example.org"],
        )

    def test_missing_email_names_the_student(self):
        with self.assertRaisesRegex(ValueError, "Abel, Amy"):
            contact_rows([Student("1", "Abel", "Amy", "A1")])

    def test_empty_list_raises(self):
        with self.assertRaises(ValueError):
            contact_rows([])


if __name__ == "__main__":
    unittest.main()
